class TrainGateReport(BaseModel):
    """
    The deterministic promotion gate's verdict, reported in full so a held
    run is as auditable as a promoted one (null results are data).
    """

    effect: Annotated[
        float,
        Field(
            description='Challenger − champion primary quality metric on the held-out eval\nslice (nDCG for fusion and retrieval-profile comparisons).'
        ),
    ]
    hit_rate_delta: float | None = None
    labeled: Annotated[
        int, Field(description='Labeled eval probes the decision is over.', ge=0)
    ]
    latency_p50_ratio: Annotated[
        float | None,
        Field(
            description='Challenger / champion latency ratios at each reported percentile.'
        ),
    ] = None
    latency_p95_ratio: float | None = None
    latency_p99_ratio: float | None = None
    latency_ratio: Annotated[
        float,
        Field(
            description='Legacy decision latency ratio. For configuration shadow evaluation this\nis the worst of p50/p95/p99; older trainer kinds may use their primary\nlatency statistic.'
        ),
    ]
    max_latency_ratio: Annotated[
        float,
        Field(
            description='Ceiling on `latency_ratio` — unoptimized metrics are guarded, never\ntraded away.'
        ),
    ]
    min_effect: Annotated[
        float, Field(description='Minimum effect size for promotion (refuses noise).')
    ]
    min_labeled: Annotated[
        int, Field(description='Minimum labeled probes for any promotion.', ge=0)
    ]
    mrr_delta: float | None = None
    ndcg_ci95_lower: Annotated[
        float | None,
        Field(
            description='Deterministic paired-bootstrap 95% interval for challenger − champion\nnDCG@10. Promotion requires the lower bound to be at least zero.'
        ),
    ] = None
    ndcg_ci95_upper: float | None = None
    non_inferiority_boundary: float | None = None
    passed: bool
    reason: Annotated[
        str,
        Field(description='Human-readable one-liner for the console status surface.'),
    ]
    recall_delta: Annotated[
        float | None,
        Field(
            description='Paired held-out retrieval deltas. When present, all must be\nnon-negative.'
        ),
    ] = None


