class TrainModelRequest(BaseModel):
    """
    `POST /v1/models/train` — run the deterministic trainer once for one
    kind: build an execution-verified probe set, search a bounded candidate
    space on the train slice, gate challenger vs champion on the held-out
    eval slice, record the run in the WS9 registry either way, and promote
    only when the gate passes. This is the same tick the auto-train cadence
    fires; calling it by hand is always safe (bounded, snapshot-pinned).
    """

    force: Annotated[
        bool | None,
        Field(
            description='Train even when the cadence says retraining is not yet due.'
        ),
    ] = None
    kind: Annotated[str, Field(description='One of [`TRAINABLE_KINDS`].')]
    max_probes: Annotated[
        int | None,
        Field(
            description='Probe-set ceiling (train + eval slices together). Clamped server-side.',
            ge=0,
        ),
    ] = None
    probes: Annotated[
        list[ShadowQuery] | None,
        Field(
            description='Bring-your-own labeled probes (captured signals, hand-written evals).\n`None` ⇒ execution-verified synthetic pairs from the graph itself.'
        ),
    ] = None
    source_job_id: Annotated[
        str | None,
        Field(
            description='Server-assigned durable execution identity. Clients normally omit it;\nit is persisted into the model manifest to make worker redelivery safe.'
        ),
    ] = None


